102:         &self,
103:         turn_state: Option<&Mutex<TurnState>>,
104:     ) -> (
105:         watch::Receiver<InputQueueActivity>,
106:         Option<InputQueueActivity>,
107:     ) {
108:         let activity_rx = self.activity_tx.subscribe();
109:         let has_pending_steer = if let Some(turn_state) = turn_state {
110:             turn_state.lock().await.pending_input.has_pending_input()
111:         } else {
112:             false
113:         };
114:         let pending_activity = if has_pending_steer {
115:             Some(InputQueueActivity::Steer)
116:         } else if self.has_pending_mailbox_items().await {
117:             Some(InputQueueActivity::Mailbox)
118:         } else {
119:             None
120:         };
