152:     pub(crate) async fn drain_mailbox_input_items(&self) -> (Vec<TurnInput>, TurnStartOptions) {
153:         let pending_mails = self
154:             .mailbox_pending_mails
155:             .lock()
156:             .await
157:             .drain(..)
158:             .collect::<Vec<_>>();
159:         // A later follow-up supersedes the earlier choice, including an omitted choice.
160:         let mut start_options = pending_mails
161:             .iter()
162:             .rev()
163:             .find(|mail| mail.communication.trigger_turn)
164:             .map(|mail| mail.start_options.clone())
165:             .unwrap_or_default();
166:         start_options.parent_turn_id = pending_mails
167:             .iter()
168:             .filter(|mail| mail.communication.trigger_turn)
169:             .map(|mail| mail.start_options.parent_turn_id.as_deref())
170:             .reduce(|expected, candidate| expected.filter(|id| candidate == Some(*id)))
171:             .and_then(|id| id.filter(|id| !id.trim().is_empty()).map(str::to_string));
172:         start_options.root_turn_id = pending_mails
173:             .iter()
174:             .find(|mail| mail.communication.trigger_turn)
175:             .and_then(|mail| {
176:                 mail.start_options
177:                     .parent_turn_id
178:                     .as_deref()
179:                     .filter(|id| !id.trim().is_empty())
180:                     .and(mail.start_options.root_turn_id.as_deref())
181:                     .filter(|id| !id.trim().is_empty())
182:             })
183:             .map(str::to_string);
184:         let items = pending_mails
185:             .into_iter()
186:             .map(|mail| TurnInput::InterAgentCommunication(mail.communication))
187:             .collect();
188:         (items, start_options)
189:     }
